css:
.t{background:linear-gradient(139.04deg,#fff 31.195%,#adc1f5 99.304%);font-family:Poppins,Arial,sans-serif;color:#232121}
.grid{position:absolute;inset:0;background:
  linear-gradient(90deg,rgba(40,80,200,.13) 1px,rgba(40,80,200,0) 1px) 32.6px 0/35.4px 32.2px,
  linear-gradient(180deg,rgba(40,80,200,.13) 1px,rgba(40,80,200,0) 1px) 0 23px/35.4px 32.2px;
  -webkit-mask-image:linear-gradient(139deg,rgba(0,0,0,0) 25%,rgba(0,0,0,.45) 60%,#000 100%);mask-image:linear-gradient(139deg,rgba(0,0,0,0) 25%,rgba(0,0,0,.45) 60%,#000 100%)}
.glow{position:absolute;inset:0;background:radial-gradient(circle at 18px 741px,rgba(0,64,223,.9) 0,rgba(0,64,223,.6) 120px,rgba(0,64,223,.36) 200px,rgba(0,64,223,.14) 290px,rgba(0,64,223,0) 400px)}
.art{position:absolute;left:0;top:0;width:1200px;height:628px;opacity:.87}
.left{position:absolute;left:65px;top:87px;width:640px;display:flex;flex-direction:column;align-items:flex-start}
.left>*{flex:none}
.nocta .left{left:75px;top:102px}
.lk{display:flex;flex-direction:column;align-items:flex-end;width:188px}
.lk img{width:188px;height:auto}
.lk span{margin-top:5.4px;font:700 13.6px/1 Poppins;letter-spacing:.2px;color:#232121}
.title{margin-top:18.4px;width:624px;max-height:176px;padding-bottom:5px;margin-bottom:-5px;overflow:hidden;font:700 46px/1.231 Poppins;color:#232121}
.nocta .title{margin-top:29.4px}
.title .hl{color:#0040df}
.date{margin-top:23px;height:39px;display:flex;align-items:center;gap:10.5px;padding:0 17px 0 14.7px;border-radius:3.52px;background:rgba(0,64,223,.11);font:600 19.49px/1 Poppins;color:#0935a2;white-space:nowrap}
.nocta .date{margin-top:29px}
.date svg{width:28.84px;height:28.84px;flex:none}
.cta{margin-top:49px;height:59.85px;padding:0 25px;min-width:187.7px;display:flex;align-items:center;justify-content:center;border-radius:5.785px;background:#0040df;border:.956px solid #0040df;box-shadow:0 0 83.4px 21px rgba(0,64,223,.24);font:600 18px/1 Poppins;color:#fff;white-space:nowrap}
.s{position:absolute;width:231px;height:226px}
.c3 .s:nth-child(1){left:800.5px;top:68px}
.c3 .s:nth-child(2){left:669.5px;top:319px}
.c3 .s:nth-child(3){left:920.5px;top:314px}
.c2 .s:nth-child(1){left:868px;top:76px}
.c2 .s:nth-child(2){left:676px;top:318px}
.c1 .s{left:800px;top:120px;transform:scale(1.25);transform-origin:50% 0}
.ph{position:absolute;left:25.5px;top:0;width:180px;height:180px;border-radius:50%;overflow:hidden;background:#0040df}
.ph img{width:100%;height:100%;object-fit:cover;object-position:center top}
.ph b{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font:600 52px/1 Poppins;color:#fff}
.card{position:absolute;left:0;top:153px;width:231px;height:69.9px;border-radius:10.56px;background:#fff;box-shadow:0 3px 17.7px rgba(88,87,123,.14);padding:12.5px 16px 0 22px}
.c3 .s:nth-child(n+2) .card{top:157px}
.card .n{height:18px;font:600 14.38px/18px Poppins;color:#000;white-space:nowrap;overflow:hidden}
.card .d{margin-top:3px;width:110px;max-height:24px;overflow:hidden;font:400 9.85px/11.64px Poppins;color:#000}
.card.nologo .d{width:190px}
.co{position:absolute;right:16px;top:26px;width:84px;height:33px;display:flex;align-items:center;justify-content:flex-end}
.co img{max-width:84px;max-height:33px;object-fit:contain;object-position:right center}
.co b{font:600 10.5px/1.15 Poppins;color:#0040df;text-align:right;max-height:36px;overflow:hidden}
